// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ListIncidents List incidents (newest first)
	// (GET /incidents)
	ListIncidents(ctx context.Context, request ListIncidentsRequestObject) (ListIncidentsResponseObject, error)
	// GetIncident One incident with its articles, per-article observations and audit trail
	// (GET /incidents/{id})
	GetIncident(ctx context.Context, request GetIncidentRequestObject) (GetIncidentResponseObject, error)
	// PipelineSummary Counters, and LLM spend by day and model
	// (GET /ops/pipeline)
	PipelineSummary(ctx context.Context, request PipelineSummaryRequestObject) (PipelineSummaryResponseObject, error)
	// ListSources Discovery sources with quality metrics and schedule state
	// (GET /ops/sources)
	ListSources(ctx context.Context, request ListSourcesRequestObject) (ListSourcesResponseObject, error)

	// (POST /ops/sources/{slug}/schedule)
	ControlSchedule(ctx context.Context, request ControlScheduleRequestObject) (ControlScheduleResponseObject, error)
	// ListReviews Possible duplicate matches awaiting a human decision
	// (GET /reviews)
	ListReviews(ctx context.Context, request ListReviewsRequestObject) (ListReviewsResponseObject, error)
	// DecideReview Approve (merge) or reject a possible duplicate
	// (POST /reviews/{id}/decision)
	DecideReview(ctx context.Context, request DecideReviewRequestObject) (DecideReviewResponseObject, error)
	// StatsBreakdown Group incidents by one dimension
	// (GET /stats/breakdown)
	StatsBreakdown(ctx context.Context, request StatsBreakdownRequestObject) (StatsBreakdownResponseObject, error)

	// (GET /stats/summary)
	StatsSummary(ctx context.Context, request StatsSummaryRequestObject) (StatsSummaryResponseObject, error)

	// (GET /stats/timeseries)
	StatsTimeseries(ctx context.Context, request StatsTimeseriesRequestObject) (StatsTimeseriesResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

